using System.Windows; namespace CloudServer; public partial class AdminWindow:Window { readonly StateStore store; public AdminWindow(StateStore s){InitializeComponent();BrandImage.Source=BrandLogo.Image();store=s;AddUserButton.Click+=(_,__)=>AddUser();EditUserButton.Click+=(_,__)=>EditUser();DeleteUserButton.Click+=(_,__)=>DeleteUser();AddStorageButton.Click+=(_,__)=>AddStorage();EditStorageButton.Click+=(_,__)=>EditStorage();DeleteStorageButton.Click+=(_,__)=>DeleteStorage();Refresh();} void Refresh(){UserCount.Text=store.State.Users.Count.ToString();StorageCount.Text=store.State.Storage.Count.ToString();UsersGrid.ItemsSource=store.State.Users.Select(u=>new UserRow(u.Id,u.UserName,u.IsAdmin?"Administrator":"Benutzer",Format(u.QuotaBytes))).ToList();StorageGrid.ItemsSource=store.State.Storage.Select(x=>new StorageRow(x.Id,x.Name,x.Role,store.State.Users.FirstOrDefault(u=>u.Id==x.UserId)?.UserName??store.State.Groups.FirstOrDefault(g=>g.Id==x.GroupId)?.Name??"Nicht zugewiesen",Format(x.QuotaBytes))).ToList();} static string Format(long b)=>b<=0?"Unbegrenzt":b>=1099511627776L?$"{b/1099511627776d:N2} TB":$"{b/1073741824d:N0} GB"; void AddUser(){var d=new UserDialog{Owner=this};if(d.ShowDialog()!=true)return;store.State.Users.Add(new UserAccount{UserName=d.UserName,DisplayName=d.DisplayName,PasswordHash=StateStore.Hash(d.Password),QuotaBytes=d.QuotaBytes});store.Save();Refresh();} void EditUser(){if(UsersGrid.SelectedItem is not UserRow row)return;var u=store.State.Users.FirstOrDefault(x=>x.Id==row.Id);if(u==null)return;var d=new UserDialog(u.UserName,u.DisplayName,u.QuotaBytes){Owner=this};if(d.ShowDialog()!=true)return;u.UserName=d.UserName;u.DisplayName=d.DisplayName;u.QuotaBytes=d.QuotaBytes;if(!string.IsNullOrWhiteSpace(d.Password))u.PasswordHash=StateStore.Hash(d.Password);store.Save();Refresh();} void DeleteUser(){if(UsersGrid.SelectedItem is not UserRow row)return;var u=store.State.Users.FirstOrDefault(x=>x.Id==row.Id);if(u==null||u.IsAdmin)return;if(System.Windows.MessageBox.Show($"Benutzer {u.UserName} löschen?","Bestätigen",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;store.State.Users.Remove(u);store.Save();Refresh();} void AddStorage(){var d=new StorageDialog(store){Owner=this};if(d.ShowDialog()!=true)return;store.State.Storage.Add(new StorageAssignment{Name=d.StorageName,Path=d.StoragePath,Role=d.Role,UserId=d.UserId,GroupId=d.GroupId,QuotaBytes=d.QuotaBytes});store.Save();Refresh();} void EditStorage(){if(StorageGrid.SelectedItem is not StorageRow row)return;var s=store.State.Storage.FirstOrDefault(x=>x.Id==row.Id);if(s==null)return;var d=new StorageDialog(store,s){Owner=this};if(d.ShowDialog()!=true)return;s.Name=d.StorageName;s.Path=d.StoragePath;s.Role=d.Role;s.UserId=d.UserId;s.GroupId=d.GroupId;s.QuotaBytes=d.QuotaBytes;store.Save();Refresh();} void DeleteStorage(){if(StorageGrid.SelectedItem is not StorageRow row)return;var s=store.State.Storage.FirstOrDefault(x=>x.Id==row.Id);if(s==null)return;if(MessageBox.Show($"Speicherzuweisung „{s.Name}“ entfernen?\n\nEs werden keine Dateien gelöscht oder formatiert.","Speicher entfernen",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;store.State.Storage.Remove(s);store.Save();Refresh();}  sealed record UserRow(string Id,string User,string Role,string Quota); sealed record StorageRow(string Id,string Name,string Role,string Assigned,string Quota); }